steps = [
    step("CORS(app) 默认配置:请求带 Origin 头时,响应是 Access-Control-Allow-Origin: http://app.example(把请求的 Origin 原样回显)加 Vary: Origin;请求不带 Origin 头(不是跨域请求)时是 Access-Control-Allow-Origin: *。", t=tl(S(1)), done=lidx(S(1), '带 Origin', '不带 Origin'), kv=KV([['带 Origin', '回显 Origin + Vary: Origin'], ['不带 Origin', '*']], ['带 Origin'])),
    step("预检请求(OPTIONS 加 Access-Control-Request-Method 与 -Headers):默认返回 200、空正文,头里有 Allow-Origin、Allow-Headers(把请求的 content-type, x-token 回显)、Allow-Methods(DELETE, GET, HEAD, OPTIONS, PATCH, POST, PUT)。配置 methods=[GET, POST] 后,请求 PUT 的预检仍是 200,但没有任何 CORS 头——靠头缺失来拒绝,浏览器据此拒绝后续请求。", t=tl(S(2)), done=lidx(S(2), '200 {'), mark=lidx(S(2), 'methods=[GET,POST]'), kv=KV([['预检通过', '200 + Allow-* 头'], ['预检不通过', '200,但没有 CORS 头']], ['预检不通过'])),
    step("origins 白名单:允许的 Origin 被回显;不在名单里的 http://evil.example 没有任何 CORS 头,但请求照样被处理(状态码 200、正文 {ok: true})——CORS 不是服务端的访问控制,拦截动作由浏览器完成。evil 的预检同样是 200、没有头。", t=tl(S(3)), done=lidx(S(3), 'app.example'), mark=lidx(S(3), 'evil.example'), kv=KV([['不在白名单', '没有 CORS 头,请求仍被处理'], ['谁来拦', '浏览器']], ['不在白名单'])),
    step("supports_credentials=True:origins 是默认的 * 时,Allow-Origin 回显请求的 Origin、带 Access-Control-Allow-Credentials: true 与 Vary: Origin;origins=[A] 时同样回显 A 并带 Allow-Credentials: true。浏览器规定带凭证的响应里 Allow-Origin 不能是 *,所以这里总是回显具体的源。", t=tl(S(4)), done=lidx(S(4), 'credentials'), kv=KV([['Allow-Credentials', 'true'], ['Allow-Origin', '具体的源,不是 *']], ['Allow-Credentials'])),
    step("resources 只给 /api/* 开 CORS 并设 expose_headers=['X-Total']:/api/x 有 Allow-Origin 与 Expose-Headers: X-Total;/private 没有任何头;@cross_origin(origins=['http://one.example']) 装饰的 /one 只对 one.example 开放,对 app.example 没有头。", t=tl(S(5)), done=lidx(S(5), '/api/x', '/one'), mark=lidx(S(5), '/private'), kv=KV([['resources', '按路径匹配开启'], ['@cross_origin', '单个视图单独配置'], ['expose_headers', '让 JS 能读到自定义响应头']], ['resources'])),
    step("出错的响应也带 CORS 头:未处理的异常 500、不存在的路径 404、abort(403) 的响应里 Allow-Origin 都是 http://app.example(TESTING=False 时的 500 也是)。所以浏览器里看到「CORS 错误」时,多半不是出错响应缺头,而是预检失败或 Origin 不在名单里——这一条只在 Flask-CORS 的默认配置下验证。", t=tl(S(6)), done=lidx(S(6), '500', '404', '403'), kv=KV([['500 / 404 / 403', '都带 Allow-Origin'], ['常见误判', '以为 500 没有 CORS 头']], ['500 / 404 / 403'])),
    step(f"真实的无头 Chrome(页面与接口端口不同):接口没开 CORS 时 4 个 fetch 全部是 TypeError: Failed to fetch,但服务端日志里 GET /data 与 GET /me(cookie 随请求发出了)都被处理了;POST JSON 和带 X-Token 头的请求在预检(OPTIONS)就被拦下,服务端根本没收到 POST。CORS(app) 默认配置下前 3 个成功,带凭证的 /me 失败(没有 Allow-Credentials);origins=[页面源] 同样;只有再加 supports_credentials=True,/me 才成功,拿到 {{sid: abc123}}。", t=tl(S(7)), done=lidx(S(7), '服务端实际收到', 'supports_credentials'), mark=lidx(S(7), '接口没开 CORS', 'FAIL'), kv=KV([['没开 CORS', '请求到了服务端,响应被浏览器拦'], ['非简单请求', '预检不过就不发真正的请求'], ['带 cookie', '需要 supports_credentials + 具体源']], ['没开 CORS'])),
]
